import {createDocumentRows} from './admin-document-rows.mjs';
import {invoiceBasisEditor} from './invoice-basis-editor.mjs?v=2';
const titles={confirmation:'Ordrebekræftelse',basis:'Fakturagrundlag',shipment:'Forsendelsesbekræftelse',receipt:'Kvittering'};
const el=(tag,text)=>{const node=document.createElement(tag);if(text)node.textContent=text;return node;};
const kr=n=>n===null?'Mangler':(n/100).toLocaleString('da-DK',{minimumFractionDigits:2,maximumFractionDigits:2})+' kr.';
export function documentPanel(order,api,sharedRows,{onChanged=async()=>{}}={}){
 const box=el('section'),toolbar=el('div'),editor=el('div'),status=el('p');box.className='order-documents';const rows=sharedRows||createDocumentRows(order);toolbar.append(rows.root);status.setAttribute('role','status');
 box.append(el('h3','Dokumenter og afsendelse'),el('p','Opret PDF gemmer et dokument. PDF-rettelser ændrer ikke ordren. Mail sendes først efter din gennemgang.'),toolbar,status,editor,rows.reviewHost);
 const url=`/api/pf-orders/${order.id}/documents`;const history=el('details');history.append(el('summary','Tidligere genererede PDF’er'));box.append(history);const latest=new Map();function addHistory(record){const row=rows.ensure(record.type),previous=latest.get(record.type);if(!previous||Number(record.version||0)>=Number(previous.version||0)){latest.set(record.type,record);if(row.download)row.download.remove();row.download=el('a','Hent PDF'+(record.version?' · v'+record.version:''));row.download.href=url+'/'+record.id;row.download.target='_blank';row.download.rel='noopener';row.actions.append(row.download);if(['basis','receipt'].includes(record.type)){if(row.sendPDF)row.sendPDF.remove();row.sendPDF=el('button','Gennemse og send PDF');row.sendPDF.type='button';row.sendPDF.onclick=()=>{editor.replaceChildren();sendDocument(record,editor);};row.actions.append(row.sendPDF);}row.setStatus('pdf','PDF klar'+(record.version?' · version '+record.version:''));const sent=(order.attention?.correspondence||[]).filter(m=>m.documentId===record.id&&m.status==='sent').sort((a,b)=>String(b.sentAt||b.createdAt).localeCompare(String(a.sentAt||a.createdAt)))[0];row.setSent('pdf',sent);if(sent){row.setStatus('mail','Accepteret af mailserver · '+sent.to+' · '+new Date(sent.sentAt||sent.createdAt).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'}));if(row.sendPDF)row.sendPDF.textContent='Gennemse og gensend PDF';}}const item=el('section'),a=el('a',record.title+(record.version?' · version '+record.version:'')+' · '+new Date(record.createdAt).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'}));a.href=url+'/'+record.id;a.target='_blank';a.rel='noopener';const edit=el('button','Opret rettet version'),send=el('button',record.type==='basis'?'Send PDF til Financial':'Send PDF til kunden');edit.type=send.type='button';edit.onclick=()=>open(record.type,record.id);send.onclick=()=>sendDocument(record,item);item.append(a,edit,send);history.append(item);}
 let sendReview=0;async function sendDocument(record,container){const current=++sendReview;
 let snapshot;try{snapshot=await(await api(url+'?snapshot='+record.id)).json();}catch(error){status.textContent=error.message;return;}
 if(current!==sendReview)return;const form=el('form'),to=el('input'),subject=el('input'),body=el('textarea'),send=el('button','Send denne PDF-version');form.className='document-send-review';const basis=record.type==='basis',requestId=crypto.randomUUID();to.type='email';to.required=true;to.placeholder=basis?'Bogholderens e-mail':'Kundens e-mail';to.value=basis?rows.accountantEmail||snapshot.company?.accountantEmail||snapshot.accountantEmail||'':snapshot.customer?.email||order.shipping?.email||'';subject.value=record.title+' · Smerch-ordre '+(order.pfOrderNumber||order.purchaseOrderNumber);subject.required=true;body.value=basis?'Her er fakturagrundlaget til manuel oprettelse i e-conomic. Dokumentet er ikke en faktura.':'Her er '+record.title.toLocaleLowerCase('da')+' for din ordre hos Smerch.';body.required=true;to.setAttribute('aria-label','Modtagerens e-mail');subject.setAttribute('aria-label','Emne');body.setAttribute('aria-label','Besked');const cancel=el('button','Luk');cancel.type='button';cancel.onclick=()=>form.remove();form.append(el('h3',basis?'Send fakturagrundlag til Financial':'Send '+record.title.toLocaleLowerCase('da')+' til kunden'),el('p',basis?'Internt arbejdsdokument · ikke en faktura.':'Kontrollér modtager og PDF før afsendelse.'),to,subject,body,send,cancel);container.append(form);let submitting=false;form.onsubmit=async e=>{e.preventDefault();if(submitting)return;submitting=true;send.disabled=true;try{const result=await(await api(url,'POST',{action:'send',documentId:record.id,audience:basis?'accountant':'customer',to:to.value,subject:subject.value,text:body.value,requestId})).json();const message=result.status==='sent'?'PDF accepteret af mailserver · '+to.value+'.':result.error||'Afsendelsen afventer afstemning. Kontrollér mailkontoen før et nyt forsøg.';status.textContent=message;send.textContent=result.status==='sent'?'Accepteret af mailserver':'Afventer afstemning';rows.ensure(record.type).setStatus('mail',message);rows.ensure(record.type).setSent('pdf',result);for(const field of [to,subject,body])field.disabled=true;try{await onChanged(result,message);}catch{status.textContent=message+' Visningen kunne ikke opdateres. Opdatér siden; send ikke igen.';}}catch(error){status.textContent=error.message;submitting=false;send.disabled=false;}};
 }

 api(url).then(r=>r.json()).then(data=>{rows.accountantEmail=data.company?.accountantEmail||'';rows.ensure('basis').email.textContent=rows.accountantEmail||'Bogholderens e-mail mangler';for(const record of data.documents||[])addHistory(record);for(const option of data.options){const row=rows.ensure(option.type),button=el('button','Opret PDF');button.type='button';button.disabled=!!option.reason;button.title=option.reason||'Gennemse oplysninger og opret PDF';button.setAttribute('aria-label','Opret PDF · '+titles[option.type]);button.onclick=()=>open(option.type);if(!latest.has(option.type))row.setStatus('pdf',option.reason?rows.shortReason(option.type,option.reason):option.type==='basis'?'Opret grundlag til Financial.':'PDF kan oprettes.');row.actions.append(button);}}).catch(e=>status.textContent=e.message);
 async function open(type,editId,deliveryKey){status.textContent='Henter ordreoplysninger…';editor.replaceChildren();try{const d=await(await api(url+(editId?'?edit='+encodeURIComponent(editId):'?type='+type+(deliveryKey?'&delivery='+encodeURIComponent(deliveryKey):'')))).json();d.requestId=crypto.randomUUID();status.textContent='';if(type==='basis'){invoiceBasisEditor(d,api,url,addHistory);return;}const form=el('form'),fields=el('div'),preview=el('div');fields.className='document-fields';form.append(fields);editor.append(form,preview);fields.append(el('h3',titles[type]+' · gennemse og ret'),el('p','Ordrereference: '+d.reference));
 if(type==='shipment'&&order.shipment?.deliveries?.filter(r=>r.key).length>1){const label=el('label','Vælg den konkrete forsendelse'),select=el('select');for(const row of order.shipment.deliveries.filter(r=>r.key)){const option=el('option',[row.shipDate,row.carrier,...(row.tracking||[])].filter(Boolean).join(' · '));option.value=row.key;option.selected=row.key===d.shipmentKey;select.append(option);}select.onchange=()=>open('shipment',null,select.value);label.append(select);fields.append(label,el('p','Dokumentet gælder kun den valgte forsendelse. Ukendte vareantal skal afstemmes manuelt.'));}
 const inputs=[];let generatedLink;
 function field(parent,label,obj,key,{multiline=false,money=false,number=false,readonly=false}={}){const wrap=el('label'),caption=el('span',label),input=el(multiline?'textarea':'input');input.value=money?(obj[key]===null?'':(obj[key]/100).toFixed(2)):obj[key]??'';if(!multiline)input.type=number||money?'number':'text';if(number||money){input.step=money?'0.01':'1';input.min='0';}input.readOnly=readonly;input.oninput=()=>{d.requestId=crypto.randomUUID();obj[key]=money?(input.value===''?null:Math.round(Number(input.value)*100)):number?(input.value===''?null:Number(input.value)):input.value;preview.replaceChildren();if(generatedLink)generatedLink.remove();};wrap.append(caption,input);parent.append(wrap);inputs.push(input);return input;}
 field(fields,'Ordredato (ÅÅÅÅ-MM-DD)',d,'date');
 const sender=el('details');sender.append(el('summary','Afsender og virksomhedsindstillinger'));fields.append(sender);sender.append(el('p','Smerch står som afsender. Gem kun fælles oplysninger som standard.'));
 for(const [key,label] of Object.entries({legalName:'Juridisk virksomhed',address:'Adresse',cvr:'CVR',email:'E-mail',phone:'Telefon',accountantEmail:'Bogholderens e-mail (valgfrit)'}))field(sender,label,d.company,key,{multiline:key==='address'});
 field(sender,'Standardbetalingsbetingelser (ingen kreditfrist antages)',d.company,'paymentTerms',{multiline:true});field(sender,'Standardbemærkning til bogholderen',d.company,'accountantNotes',{multiline:true});
 const save=el('button','Gem som virksomhedsindstillinger');save.type='button';save.onclick=async()=>{save.disabled=true;try{await api(url,'POST',{action:'settings',company:d.company});status.textContent='Virksomhedsindstillingerne er gemt til kommende dokumenter.';}catch(e){status.textContent=e.message;}finally{save.disabled=false;}};sender.append(save);
 fields.append(el('h4','Kunde'));
 for(const [key,label] of Object.entries({name:'Navn / firma',address:'Faktureringsadresse',email:'E-mail',cvr:'CVR (valgfrit)',ean:'EAN (valgfrit)',reference:'Kundereference (valgfrit)'})){if(type==='shipment'&&key==='address')continue;field(fields,label,d.customer,key,{multiline:key==='address'});}
 if(type!=='shipment'){const copy=el('button','Brug leveringsadresse som faktureringsadresse');copy.type='button';copy.onclick=()=>{d.requestId=crypto.randomUUID();d.customer.address=d.deliveryAddress;const input=inputs.find(i=>i.parentElement.firstChild.textContent==='Faktureringsadresse');input.value=d.deliveryAddress;preview.replaceChildren();};fields.append(copy);}
 if(type==='shipment'){field(fields,'Leveringsadresse',d,'deliveryAddress',{multiline:true});field(fields,'Afsendelsesdato (ÅÅÅÅ-MM-DD)',d,'shipDate');field(fields,'Transportør (valgfrit)',d,'carrier');field(fields,'Trackingnummer og link (valgfrit)',d,'tracking',{multiline:true});fields.append(el('p','Kontrollér afsendte antal. Ved delvis afsendelse skal antal angives; brug 0 for varer, der ikke er med.'));}
 fields.append(el('h4',type==='shipment'?'Afsendte produkter':'Varelinjer · beløb i DKK'));
 for(const [i,line] of d.lines.entries()){const row=el('fieldset');row.append(el('legend','Vare '+(i+1)));fields.append(row);field(row,'Produktbeskrivelse',line,'description',{multiline:true});field(row,'Variant / varenummer / tryk',line,'variant',{multiline:true});field(row,type==='shipment'?'Afsendt antal (maks. '+line.maxQuantity+')':'Antal',line,'quantity',{number:true,readonly:type==='receipt'});if(type!=='shipment'){field(row,'Linjetotal ekskl. moms, inkl. tryk og opstart',line,'net',{money:true,readonly:type==='receipt'});field(row,'Rabat, allerede indregnet (valgfrit)',line,'discount');}}
 if(type!=='shipment'){field(fields,'Fragt ekskl. moms',d,'freight',{money:true,readonly:type==='receipt'});field(fields,'Moms i alt',d,'vat',{money:true,readonly:type==='receipt'});fields.append(el('p','Moms hentes fra ordren. Ved rettede beløb skal moms også kontrolleres.'));field(fields,'Betalingsbetingelser',d,'paymentTerms',{multiline:true,readonly:d.paymentProvider==='bank_transfer'});fields.append(el('p',d.paymentStatus+(type==='receipt'?' · '+new Date(d.paidAt).toLocaleString('da-DK'):'')));}
 field(fields,type==='basis'?'Bemærkninger til bogholderen':'Bemærkninger til kunden',d,'notes',{multiline:true});
 const review=el('button','Gennemse dokument');review.type='submit';form.append(review);form.onsubmit=async event=>{event.preventDefault();review.disabled=true;preview.replaceChildren();status.textContent='Kontrollerer oplysninger…';try{const checked=await(await api(url,'POST',{action:'review',document:d})).json();status.textContent='';preview.append(el('h4','Kontrol før PDF'));if(checked.missing.length){preview.append(el('p','Følgende oplysninger mangler eller er ugyldige:'));const list=el('ul');checked.missing.forEach(m=>list.append(el('li',m)));preview.append(list);return;}
 preview.append(el('p','Afsender: Smerch · '+checked.company.legalName),el('p','Kunde: '+checked.customer.name+' · '+(type==='shipment'?checked.deliveryAddress:checked.customer.address)));
 for(const line of checked.lines)preview.append(el('p',`${line.quantity} × ${line.description}${type==='shipment'?'':' · '+kr(line.net)+' ekskl. moms'}`));
 if(type!=='shipment')preview.append(el('strong','I alt inkl. moms: '+kr(checked.total)));
 if(checked.adjusted)preview.append(el('p','Beløb eller antal afviger fra ordren. Din bemærkning medtages til bogholderen.'));
 const generate=el('button','Generér '+titles[type]+' som PDF');generate.type='button';preview.append(generate);generate.onclick=async()=>{generate.disabled=true;try{const record=await(await api(url,'POST',{action:'generate',document:d})).json();if(record.pending){const queued=el('a','Åbn dokumentstatus på ordren');queued.href=record.workspace;preview.append(queued);status.textContent='PDF’en behandles i baggrunden. Åbn dokumentstatus for at hente den, når den er klar.';return;}generatedLink=el('a','Åbn / hent '+record.title+' (PDF)');generatedLink.href=url+'/'+record.id;generatedLink.target='_blank';generatedLink.rel='noopener';preview.append(generatedLink);addHistory(record);status.textContent='PDF’en er gemt. Brug linket til at gennemse og hente den. Ingen mail er sendt.';}catch(e){status.textContent=e.message;generate.disabled=false;}};
 }catch(e){status.textContent=e.message;}finally{review.disabled=false;preview.scrollIntoView({block:'nearest',behavior:'smooth'});}};
 }catch(e){status.textContent=e.message;}}
 return box;
}
